-- Additive staff, menu and financial ledgers; historical prices remain unchanged.
CREATE TABLE "RestaurantStaff" ("id" TEXT PRIMARY KEY,"restaurantId" TEXT NOT NULL REFERENCES "Restaurant"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"staffRole" TEXT NOT NULL CHECK ("staffRole" IN ('MANAGER','MENU','KITCHEN')),"active" BOOLEAN NOT NULL DEFAULT true,"version" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "RestaurantStaff_restaurantId_active_idx" ON "RestaurantStaff"("restaurantId","active");
CREATE TABLE "StaffInvitation" ("id" TEXT PRIMARY KEY,"restaurantId" TEXT NOT NULL REFERENCES "Restaurant"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"email" TEXT NOT NULL,"staffRole" TEXT NOT NULL CHECK ("staffRole" IN ('MANAGER','MENU','KITCHEN')),"tokenHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"consumedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "StaffInvitation_restaurantId_createdAt_idx" ON "StaffInvitation"("restaurantId","createdAt");
CREATE TABLE "MenuCategory" ("id" TEXT PRIMARY KEY,"restaurantId" TEXT NOT NULL REFERENCES "Restaurant"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"name" TEXT NOT NULL,"archivedAt" TIMESTAMP(3),"version" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "MenuCategory_restaurantId_name_key" UNIQUE("restaurantId","name"));
INSERT INTO "MenuCategory"("id","restaurantId","name") SELECT 'category_'||md5("restaurantId"||':'||category),"restaurantId",category FROM "Product" GROUP BY "restaurantId",category;
ALTER TABLE "Product" ADD COLUMN "archivedAt" TIMESTAMP(3),ADD COLUMN "version" INTEGER NOT NULL DEFAULT 0,ADD COLUMN "categoryId" TEXT REFERENCES "MenuCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
UPDATE "Product" SET "categoryId"='category_'||md5("restaurantId"||':'||category);
CREATE TABLE "ProductOption" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"name" TEXT NOT NULL,"kind" TEXT NOT NULL CHECK("kind" IN ('VARIANT','ADDON')),"price" DECIMAL(10,2) NOT NULL CHECK("price">=0 AND ("kind"<>'VARIANT' OR "price">0)),"available" BOOLEAN NOT NULL DEFAULT true,"archivedAt" TIMESTAMP(3));
CREATE INDEX "ProductOption_productId_archivedAt_idx" ON "ProductOption"("productId","archivedAt");
CREATE TABLE "MenuImage" ("id" TEXT PRIMARY KEY,"restaurantId" TEXT NOT NULL REFERENCES "Restaurant"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"bytes" BYTEA NOT NULL CHECK(octet_length("bytes")<=2097152),"contentType" TEXT NOT NULL CHECK("contentType"='image/webp'),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "OrderItem" ADD COLUMN "optionsSnapshot" JSONB;
ALTER TABLE "Order" ADD COLUMN "riderPayout" DECIMAL(10,2) CHECK("riderPayout">=0),ADD COLUMN "payoutPolicyVersion" INTEGER;
CREATE TABLE "DeliveryPolicy" ("id" TEXT PRIMARY KEY DEFAULT 'default',"deliveryFee" DECIMAL(10,2) NOT NULL DEFAULT 35 CHECK("deliveryFee">=0),"freeThreshold" DECIMAL(10,2) NOT NULL DEFAULT 499 CHECK("freeThreshold">=0),"riderBase" DECIMAL(10,2) NOT NULL DEFAULT 25 CHECK("riderBase">=0),"riderFeeShareBps" INTEGER NOT NULL DEFAULT 0 CHECK("riderFeeShareBps" BETWEEN 0 AND 10000),"version" INTEGER NOT NULL DEFAULT 0);
INSERT INTO "DeliveryPolicy"("id") VALUES ('default');
CREATE TABLE "RiderSettlement" ("id" TEXT PRIMARY KEY,"riderId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"amount" DECIMAL(10,2) NOT NULL CHECK("amount">=0),"reference" TEXT NOT NULL UNIQUE,"requestHash" TEXT NOT NULL,"receivedById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "RiderSettlement_riderId_createdAt_idx" ON "RiderSettlement"("riderId","createdAt");
CREATE TABLE "RiderEarning" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL UNIQUE REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"riderId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"amount" DECIMAL(10,2) NOT NULL CHECK("amount">=0),"policyVersion" INTEGER NOT NULL,"settlementId" TEXT REFERENCES "RiderSettlement"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "RiderEarning_riderId_createdAt_idx" ON "RiderEarning"("riderId","createdAt");
-- Initial policy applies explicitly to completed historical deliveries; no historical order fields are rewritten.
INSERT INTO "RiderEarning"("id","orderId","riderId","amount","policyVersion","createdAt") SELECT 'earning_'||md5(id),id,"deliveryPartnerId",25,0,"updatedAt" FROM "Order" WHERE status='DELIVERED' AND "deliveryPartnerId" IS NOT NULL;
